(let [projection (db/carried-projection (db/db (boot/connection "default"))) state (delay projection) _ @state sink (java.util.concurrent.ConcurrentHashMap.)] (binding [seon.batch/*world* (assoc seon.batch/*world* :seon.batch/sink sink)] (schema/call-with-projection-state state #(Thread/sleep 20))) (into [] (keep (fn [[[sym _] counter]] (when (= sym 'seon.schema/call-with-projection-state) {:function sym :calls (.get ^java.util.concurrent.atomic.AtomicLongArray counter 0) :inclusive-ms (/ (.get ^java.util.concurrent.atomic.AtomicLongArray counter 1) 1e6) :self-ms (/ (.get ^java.util.concurrent.atomic.AtomicLongArray counter 2) 1e6)}))) sink))
